  /// Resolves the best available logo URL for a channel.
  static String resolve(Channel channel) {
    // 1. Direct exact clean name
    final exact = _normalize(channel.name);
    if (_logos.containsKey(exact)) return _logos[exact]!;

    // 2. Base name without resolution tags
    final base = _baseNormalize(channel.name);
    if (_logos.containsKey(base)) return _logos[base]!;

    // 3. Try & -> and conversion
    if (channel.name.contains('&')) {
      final andName = channel.name.replaceAll('&', 'and');
      final andExact = _normalize(andName);
      if (_logos.containsKey(andExact)) return _logos[andExact]!;
      final andBase = _baseNormalize(andName);
      if (_logos.containsKey(andBase)) return _logos[andBase]!;
    }

    // 4. Check tvg-id
    if (channel.id.isNotEmpty) {
      final idKey = _normalize(channel.id.split('@').first);
      if (_logos.containsKey(idKey)) return _logos[idKey]!;
      final idBase = _baseNormalize(channel.id.split('@').first);
      if (_logos.containsKey(idBase)) return _logos[idBase]!;
    }

    // 5. If channel already has an active logo URL from playlist, use it
    if (channel.logo.isNotEmpty && channel.logo.startsWith('http')) {
      return channel.logo;
    }

    // 6. Smart prefix/contains match for key >= 3 chars
    if (base.length >= 3) {
      for (final entry in _logos.entries) {
        if (entry.key.length >= 3) {
          if (entry.key.startsWith(base) || base.startsWith(entry.key)) {
            return entry.value;
          }
        }
      }
    }

    return '';
  }

  static String _normalize(String s) {
    return s.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]'), '').trim();
  }

  static String _baseNormalize(String s) {
    var out = s.toLowerCase();
    out = out.replaceAll(RegExp(r'\((?:1080p|720p|576p|360p|480p|2160p|4k|sd|hd)\)'), '');
    out = out.replaceAll(RegExp(r'\[[^\]]*\]'), '');
    out = out.replaceAll(RegExp(r'\b(?:1080p|720p|576p|360p|480p|4k|uhd|fhd|sd|hd|not247)\b'), '');
    return out.replaceAll(RegExp(r'[^a-z0-9]'), '').trim();
  }
}
